"""Shared contract fixtures: generated by the server tests, served by the phone's fake.

Regenerate after an intentional contract change:
    WEAVER_UPDATE_FIXTURES=1 uv run --project server pytest server/tests/mobile/test_fixtures.py
"""

import json
import os
import re

import pytest
from fastapi.routing import APIRoute

from weaver.mobile.api import PREFIX

from .contract import FIXTURES, committed, dump
from .helpers import Harness
from .scenarios import all_groups


@pytest.fixture(scope="module")
def generated(tmp_path_factory):
    return all_groups(tmp_path_factory.mktemp("fixtures"))


def test_fixtures_match_what_the_server_produces(generated):
    if os.environ.get("WEAVER_UPDATE_FIXTURES") == "1":
        FIXTURES.mkdir(parents=True, exist_ok=True)
        for group, document in generated.items():
            committed(group).write_text(dump(document))
        pytest.skip("fixtures rewritten")
    assert {p.stem for p in FIXTURES.glob("*.json")} == set(generated)
    for group, document in generated.items():
        assert json.loads(committed(group).read_text()) == document, group
        assert committed(group).read_text() == dump(document), group  # stable bytes


def test_every_endpoint_and_error_class_is_covered(generated, tmp_path):
    app = Harness(tmp_path).app
    routes = [
        r for r in app.routes if isinstance(r, APIRoute) and r.path.startswith(PREFIX)
    ]
    seen = {
        (c["request"]["method"], c["request"]["path"]): c["response"]["status"]
        for document in generated.values()
        for c in document["cases"]
        if "request" in c
    }
    for route in routes:
        for method in route.methods or ():
            assert any(
                m == method and route.path_regex.fullmatch(p) for m, p in seen
            ), (method, route.path)
    statuses = {
        c["response"]["status"]
        for document in generated.values()
        for c in document["cases"]
        if "request" in c
    }
    assert {
        200,
        201,
        202,
        304,
        400,
        401,
        403,
        404,
        409,
        410,
        412,
        422,
        428,
        503,
    } <= statuses


def test_placeholders_are_stable_and_no_secret_is_recorded(generated):
    text = "".join(dump(d) for d in generated.values())
    assert not re.search(
        r"wvr_(?!0+\d+\b)[A-Za-z0-9_-]{20,}", text
    )  # only placeholders
    assert "Bearer <token>" in text
    assert re.search(r"op_[0-9a-f]{32}", text)
    assert "T00:00:00Z" in text


def test_operation_cases_use_the_decided_shape(generated):
    states = set()
    for document in generated.values():
        for case in document["cases"]:
            body = case.get("response", {}).get("body")
            if isinstance(body, dict) and "operation_id" in body:
                assert {
                    "operation_id",
                    "state",
                    "kind",
                    "target_id",
                    "target_revision",
                    "updated_at",
                } <= set(body)
                assert "status" not in body
                states.add(body["state"])
    assert states == {"queued", "applied"}


def test_thread_pages_form_one_cursor_chain(generated):
    cases = {c["name"]: c for c in generated["read"]["cases"]}
    chain = [
        cases[n]
        for n in ("threads_first_page", "threads_next_page", "threads_last_page")
    ]
    assert "cursor" not in chain[0]["request"].get("query", {})
    for page, following in zip(chain, chain[1:], strict=False):
        assert page["response"]["body"]["next_cursor"] is not None
        assert (
            following["request"]["query"]["cursor"]
            == page["response"]["body"]["next_cursor"]
        )
    assert chain[-1]["response"]["body"]["next_cursor"] is None
    seqs = [t["seq"] for c in chain for t in c["response"]["body"]["items"]]
    assert seqs == list(range(1, len(seqs) + 1))  # contiguous, no gap or repeat
    assert len({c["request"]["query"]["limit"] for c in chain}) == 1
